// Final Report Aggregator - Intelligence Grade (DOCX Enhanced)
const htmlData = $('1. HTML Parser').first().json;
const perplexityResult = $('2. Perplexity OSINT Verification').first().json;
const openaiCorrelation = $('3. OpenAI Data Correlation').first().json;
const psychProfile = $('4. Anthropic Psychological Profile').first().json;
const pwdAnalysis = $('5. Password Analyzer').first().json;
const securityAssessment = $('6. Security Assessor').first().json;
const narrative = $('7. Anthropic Report Narrative').first().json;

// Parse narrative JSON
let narrativeData = {};
try {
  const jsonMatch = narrative.message.content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    narrativeData = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  narrativeData = {
    executive_summary: narrative.message.content.substring(0, 1000),
    detailed_analysis: 'Reference individual section outputs for detailed analysis.',
    conclusions: 'Assessment conclusions derived from consolidated intelligence.'
  };
}

const finalReport = {
  // Report Header
  report_metadata: {
    classification: 'RISERVATO',
    title: 'INTELLIGENCE ASSESSMENT REPORT',
    subtitle: 'FidelinvestigatorAI - OSINT Investigation Product',
    case_reference: `FIDEL-${htmlData.case_id}`,
    generated_at: new Date().toISOString(),
    generated_by: 'FidelinvestigatorAI - Intelligence Grade Edition',
    report_formats: {
      json: 'This response',
      pdf: 'Generated via Python module (fidelinvestigator_ai_enhanced.py)',
      docx_company: 'Executive Vulnerability Assessment - Aziende (executive_report_generator.py)',
      docx_personal: 'Personal Vulnerability Assessment - Persone (personal_vulnerability_report.py con Claude AI)'
    },
    ai_providers: {
      osint_verification: 'Perplexity AI (Real-time)',
      data_correlation: 'OpenAI GPT-4 Turbo',
      psychological_profiling: 'Anthropic Claude Opus',
      report_narrative: 'Anthropic Claude Opus'
    },
    confidence_methodology: 'ICD 203 Analytic Standards',
    distribution: 'Authorized Recipients Only'
  },

  // Executive Summary
  executive_summary: narrativeData.executive_summary || '',

  // Raw Intelligence
  intelligence_collection: {
    extracted_identifiers: htmlData.extracted_data,
    collection_metadata: htmlData.metadata,
    collection_timestamp: htmlData.metadata.extraction_time
  },

  // OSINT Verification
  osint_verification: {
    provider: 'Perplexity AI',
    methodology: 'Real-time web intelligence gathering',
    findings: perplexityResult.choices?.[0]?.message?.content || 'N/A',
    timestamp: new Date().toISOString()
  },

  // All-Source Correlation
  correlation_analysis: {
    provider: 'OpenAI GPT-4',
    methodology: 'All-source intelligence fusion and pattern analysis',
    findings: openaiCorrelation.message?.content || 'N/A',
    detailed_narrative: narrativeData.detailed_analysis || ''
