    active_threat_count: securityAssessment.security_assessment.executive_summary.active_threats,
    credential_risk: securityAssessment.security_assessment.risk_indicators.credential_risk,
    recommended_actions: securityAssessment.security_assessment.recommended_mitigations
  },

  // Report Footer
  dissemination_controls: {
    classification: 'RISERVATO',
    handling_instructions: 'This intelligence product contains sensitive information. Handle according to organizational security protocols.',
    retention_period: '5 years from generation date',
